Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -68,9 +68,9 @@
 function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}
 addEventListener('resize',resize);resize();
 function reset(){state='count';player={x:.28,d:0,speed:0,gear:0,rpm:.2};rival={x:.72,d:0,speed:0,gear:1};countStart=performance.now();raceStart=0;document.getElementById('overlay').classList.add('hidden');document.getElementById('countdown').style.opacity=1}
 function shift(){if(state==='race'&&player.gear<5&&player.speed>18){player.gear++;flashGear()}}
-function flashGear(){const g=document.getElementBy('gear');}
+function flashGear(){const g=document.getElementById('gear');g.animate([{transform:'scale(1)'},{transform:'scale(1.35)',color:'#40d7ff'},{transform:'scale(1)'}],{duration:180});}
 const throttle=document.getElementById('throttle'),shiftBtn=document.getElementById('shift');
 function setThrottle(v){keys.throttle=v;throttle.classList.toggle('active',v)}
 throttle.addEventListener('pointerdown',e=>{e.prevent();setThrottle(true)});throttle.addEventListener('pointerup',()=>setThrottle(false));throttle.addEventListener('pointerleave',()=>setThrottle(false));
 shiftBtn.addEventListener('pointerdown',e=>{e.prevent();shift();shiftBtn.classList.add('active')});shiftBtn.addEventListener('pointerup',()=>shiftBtn.classList.remove('active'));

