     let throttleOn=keys.throttle||keys.ArrowUp||keys.KeyW||throttle.classList.contains('active');
     if(state==='race'&&throttleOn){let max=[58,92,125,158,188,205][player.gear||1];let gearBoost=1-Math.abs(player.rpm-.72)*.35;player.speed=Math.min(max,player.speed+(9+player.gear*2.7)*gearBoost*dt);}
     else if(state==='race') player.speed=Math.max(0,player.speed-22*dt);
     if(state==='race'){
-      player.d+=player.speed*.000000?0:player.speed*dt/223; // 223 mph-scale seconds approximation
+      player.d+=player.speed*dt/223;
       let rivalRate=(rival.gear<5&&rival.d>.12*rival.gear)?rival.gear++:rival.gear;
       rival.speed=Math.min(205,rival.speed+(10+rival.gear*2.15)*dt);rival.d+=rival.speed*dt/223;
       playerTime=(t-raceStart)/1000;rivalTime=rivalTime+(dt);
       if(player.d>=1||rival.d>=1){if(player.d>=rival.d)endRace(true);else endRace(false)}

